```tsx
import { FormattedMessage } from 'react-intl';

import { Badge } from './badge';

const isSamePage = (href: string, currentHref: string) => {
  try {
    const a = new URL(href, window.location.href);
    const b = new URL(currentHref, window.location.href);

    return (
      a.origin === b.origin &&
      a.pathname === b.pathname &&
      a.search === b.search
    );
  } catch {
    return false;
  }
};

export const CurrentPageBadge: React.FC<{
  href: string;
  currentHref: string;
}> = ({ href, currentHref }) => {
  if (!isSamePage(href, currentHref)) {
    return null;
  }

  return (
    <Badge
      variant='accent'
      label={
        <FormattedMessage
          id='current_page_badge.label'
          defaultMessage='You are here'
        />
      }
    />
  );
};
```

Choices I made:
- **Comparison:** both URLs go through `new URL`, so origin (scheme, host, port), path and query are compared, and the hash never takes part. Malformed URLs render nothing rather than throwing.
- **Relative hrefs:** these resolve against `window.location.href`. The spec didn't cover this, so tell me if you'd rather treat relative values differently.
- **Badge:** it reuses the existing `Badge` component with the `accent` variant. The message id is `current_page_badge.label`. I did not add it to the locale files; those are normally generated from the extraction step.

I didn't add a story or a test, to keep it small. Next step: run `yarn` and then lint and typecheck the file.
